/**
 * Build both halves of dsh-weixin-player into lib/.
 *
 * - `lib/index.js` (and the rest of `lib/**`) — the host half, plain ESM
 *   produced by `tsc`, exactly as the tests and the Loader consume it.
 * - `lib/client.js` — the browser half, in the shape DSH's client module system
 *   expects: a lazy factory registered under the package name
 *   (`window.__ModuleLoader__.load({ id, factory })`). `react`, `react-dom` and
 *   their jsx runtimes stay external because the shell's module table owns those
 *   instances; everything else is bundled.
 *
 * The host half is NOT bundled here: keeping tsc's one-file-per-module output
 * means the published import paths stay readable and the tests can import a
 * single module instead of the whole entry graph.
 */
import { build } from "esbuild";
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(fileURLToPath(import.meta.url));
const outDir = resolve(root, "lib");
const manifest = JSON.parse(await readFile(resolve(root, "package.json"), "utf8"));

/**
 * Wrap one CJS bundle body in the module-loader registration.
 *
 * The body is inserted verbatim at column zero. Indenting it is not cosmetic:
 * esbuild prints a string containing a newline as a template literal spanning
 * two lines, and prefixing those lines would insert the indentation *into the
 * string value*.
 */
function registerBundle(id, body, mapComment) {
  return [
    "// Generated by build.mjs — do not edit; edit src/ and rebuild.",
    `window.__ModuleLoader__.load({ id: ${JSON.stringify(id)},`,
    "factory(require) {",
    "var module = { exports: {} };",
    "var exports = module.exports;",
    body,
    "return module.exports;",
    "},",
    "});",
    mapComment,
    "",
  ].join("\n");
}

await mkdir(outDir, { recursive: true });

const clientResult = await build({
  bundle: true,
  sourcemap: true,
  logLevel: "info",
  legalComments: "none",
  entryPoints: [resolve(root, "src/client/index.tsx")],
  outfile: resolve(outDir, "client.js"),
  platform: "browser",
  format: "cjs",
  target: "es2022",
  jsx: "automatic",
  jsxDev: false,
  minify: true,
  define: { "process.env.NODE_ENV": '"production"' },
  external: ["react", "react/jsx-runtime", "react-dom", "react-dom/client"],
  write: false,
});

const clientJs = clientResult.outputFiles.find((file) => file.path.endsWith(".js"));
const clientMap = clientResult.outputFiles.find((file) => file.path.endsWith(".map"));
if (clientJs === undefined) throw new Error("esbuild produced no client bundle");

const mapComment = "//# sourceMappingURL=client.js.map";
const body = clientJs.text.replace(/\/\/# sourceMappingURL=.*\s*$/, "").trimEnd();
await writeFile(resolve(outDir, "client.js"), registerBundle(manifest.name, body, mapComment), "utf8");
if (clientMap !== undefined) await writeFile(resolve(outDir, "client.js.map"), clientMap.text, "utf8");

console.log(`[dsh-weixin-player] built lib/client.js (client id: ${manifest.name})`);
